'use strict';
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto');
const EMBED = {"index.html": "", "admin.html": ""};
const SEED_EMBED = {"coins": [{"name": "نمونه ۱", "color": "#f5c542", "buy": null, "sell": null, "stock": 0, "cap": 0, "commission": 0, "sort": 1, "active": true}], "settings": {"owner_card": "", "owner_phone": "", "support_id": "", "channel_id": "", "buy_enabled": "0"}};
const PORT = +process.env.PORT || 3000;
const DATA = process.env.DATA_DIR || path.join(__dirname, 'data');
const ADMIN_USER = process.env.ADMIN_USER || 'owner';
const ADMIN_PASS = process.env.ADMIN_PASS || process.env.ADMIN_PASSWORD || '';
const PUB = path.join(__dirname, 'public');
const USE_PG = !!process.env.DATABASE_URL;
let pool = null;
if (USE_PG) {
  const { Pool } = require('pg');
  const local = /localhost|127\.0\.0\.1/.test(process.env.DATABASE_URL);
  pool = new Pool({ connectionString: process.env.DATABASE_URL, ssl: local ? false : { rejectUnauthorized: false }, max: 3 });
  pool.on('error', e => console.error('pg pool error:', e.message));
} else fs.mkdirSync(path.join(DATA, 'shots'), { recursive: true });
const DBF = path.join(DATA, 'db.json');
async function q(sql, params) { try { return await pool.query(sql, params); } catch (e) { return await pool.query(sql, params); } }

let db = null, SECRET = '';
const nid = k => (db.seq[k] = (db.seq[k] || 0) + 1);
let lastSave = Promise.resolve(), saveQueued = false;
const enqueue = fn => (lastSave = lastSave.then(fn).catch(e => console.error('persist error:', e.message)));
function save() {
  if (!pool) { fs.writeFileSync(DBF + '.tmp', JSON.stringify(db)); fs.renameSync(DBF + '.tmp', DBF); return; }
  if (saveQueued) return; saveQueued = true;
  enqueue(async () => { saveQueued = false; await q('insert into kv(k,v) values($1,$2) on conflict (k) do update set v=excluded.v', ['db', JSON.stringify(db)]); });
}
async function init() {
  if (pool) {
    await q('create table if not exists kv(k text primary key, v text not null)');
    await q('create table if not exists shots(code text primary key, data bytea not null)');
    const r = await q("select v from kv where k='db'"); if (r.rows[0]) db = JSON.parse(r.rows[0].v);
  } else { try { db = JSON.parse(fs.readFileSync(DBF, 'utf8')); } catch (e) {} }
  if (!db) db = { users: [], coins: [], orders: [], tx: [], comments: [], announcements: [], seq: {},
    settings: { owner_card: '', owner_phone: '', support_id: '', channel_id: '', buy_enabled: '0' } };
  if (!db.coins.length) {
    try {
      const seed = SEED_EMBED;
      (seed.coins || []).forEach(c => db.coins.push({ id: nid('coin'), name: String(c.name), color: c.color || '#9b6bff',
        buy: c.buy == null ? null : +c.buy, sell: c.sell == null ? null : +c.sell, stock: +c.stock || 0, cap: +c.cap || 0,
        commission: +c.commission || 0, sort: +c.sort || 0, active: c.active !== false }));
      if (seed.settings) Object.assign(db.settings, seed.settings);
    } catch (e) {}
  }
  if (!db.secret) db.secret = crypto.randomBytes(32).toString('hex');
  SECRET = process.env.TOKEN_SECRET && process.env.TOKEN_SECRET.length >= 24 ? process.env.TOKEN_SECRET : db.secret;
  if (!db.users.some(u => u.role === 'admin')) {
    if (ADMIN_PASS.length >= 6) {
      db.users.push({ id: nid('user'), username: ADMIN_USER, phone: '', card: '', pw: hashPw(ADMIN_PASS), role: 'admin', balance: 0, created_at: Date.now() });
      console.log('admin account created: ' + ADMIN_USER);
    } else console.warn('WARNING: no admin exists. Set ADMIN_USER and ADMIN_PASS (min 6 chars).');
  }
  save(); await lastSave;
  console.log('storage: ' + (pool ? 'postgres' : 'file'));
}

class HttpError extends Error { constructor(s, m) { super(m); this.status = s; } }
const bad = (m, s = 400) => new HttpError(s, m);
const now = () => Date.now();
const b64 = b => Buffer.from(b).toString('base64url');
const sig = p => crypto.createHmac('sha256', SECRET).update(p).digest('base64url');
function sign(o, ttl) { const p = b64(JSON.stringify({ ...o, exp: now() + ttl })); return p + '.' + sig(p); }
function verify(t) {
  if (typeof t !== 'string') return null;
  const [p, s] = t.split('.'); if (!p || !s) return null;
  const e = sig(p); if (s.length !== e.length || !crypto.timingSafeEqual(Buffer.from(s), Buffer.from(e))) return null;
  try { const o = JSON.parse(Buffer.from(p, 'base64url')); return o.exp > now() ? o : null; } catch (e) { return null; }
}
function hashPw(pw, salt = crypto.randomBytes(16).toString('hex')) { return salt + ':' + crypto.scryptSync(pw, salt, 32).toString('hex'); }
function checkPw(pw, h) {
  if (!h || typeof pw !== 'string') return false;
  const [salt, hex] = h.split(':'); return crypto.timingSafeEqual(crypto.scryptSync(pw, salt, 32), Buffer.from(hex, 'hex'));
}
function newCode(prefix, list) { let c; do { c = prefix + (100000 + crypto.randomInt(900000)); } while (list.some(x => x.code === c)); return c; }
const tries = new Map();
function limit(req, n = 10) {
  const ip = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').split(',')[0].trim();
  const r = tries.get(ip) || { n: 0, t: now() };
  if (now() - r.t > 600000) { r.n = 0; r.t = now(); }
  if (++r.n > n) throw bad('تعداد تلاش بیش از حد است. چند دقیقه بعد دوباره امتحان کنید.', 429);
  tries.set(ip, r);
}
function body(req, max = 7e6) {
  return new Promise((ok, no) => {
    let n = 0; const c = [];
    req.on('data', d => { n += d.length; if (n > max) { no(bad('حجم درخواست زیاد است.', 413)); req.destroy(); } else c.push(d); });
    req.on('end', () => { if (!c.length) return ok({}); try { ok(JSON.parse(Buffer.concat(c))); } catch (e) { no(bad('درخواست نامعتبر است.')); } });
    req.on('error', no);
  });
}
const str = (v, max = 200) => typeof v === 'string' ? v.trim().slice(0, max) : '';
const r2 = x => Math.round(x * 100) / 100;
const recv = c => c.sell == null ? null : r2(c.sell * (1 - (c.commission || 0) / 100));
const pub = u => ({ username: u.username, phone: u.phone, card: u.card, role: u.role || 'user' });
const live = u => u && !u.deleted;
const tehranDay = t => new Date(t + 12600000).toISOString().slice(0, 10);
function shotSave(code, data) {
  const m = /^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(data || '');
  if (!m) throw bad('اسکرین‌شات نامعتبر است.');
  const buf = Buffer.from(m[2], 'base64'); if (buf.length > 5e6) throw bad('حجم عکس زیاد است.');
  if (pool) enqueue(() => q('insert into shots(code,data) values($1,$2) on conflict (code) do update set data=excluded.data', [code, buf]));
  else fs.writeFileSync(path.join(DATA, 'shots', code), buf);
  return 'image/' + m[1];
}
const shotDel = code => pool ? enqueue(() => q('delete from shots where code=$1', [code])) : fs.rm(path.join(DATA, 'shots', code), () => {});
const idStr = v => str(v, 40).replace(/^.*ble\.ir\//i, '').replace(/[@\s]/g, '');

function authUser(req) {
  const o = verify((req.headers.authorization || '').replace(/^Bearer /, ''));
  const u = o && db.users.find(x => x.id === o.id);
  if (!live(u)) throw bad('ابتدا وارد شوید', 401);
  if (u.disabled) throw bad('حساب شما مسدود شده است.', 403);
  return u;
}
const publicConfig = () => ({
  coins: db.coins.filter(c => c.active).sort((a, b) => a.sort - b.sort || a.id - b.id)
    .map(c => ({ name: c.name, color: c.color, buy: c.buy, sell: c.sell, commission: c.commission, stock: c.stock })),
  settings: db.settings,
  announcements: db.announcements.filter(a => a.active).map(a => a.text)
});
const orderOut = o => { const { shot_type, user_id, fee, ...r } = o; return r; };
const txOut = t => { const { shot_type, user_id, ...r } = t; return r; };

/* ---------------- site API ---------------- */
async function api(req, res, p, u) {
  const m = req.method; let r;
  if (p === '/config' && m === 'GET') return publicConfig();
  if (p === '/register' && m === 'POST') {
    limit(req, 20); const b = await body(req, 1e5);
    const username = str(b.username, 30), phone = str(b.phone, 11), card = str(b.card, 16), pw = typeof b.password === 'string' ? b.password : '';
    if (username.length < 3) throw bad('نام کاربری حداقل ۳ کاراکتر باشد.');
    if (!/^09\d{9}$/.test(phone)) throw bad('شماره موبایل باید ۱۱ رقم و با ۰۹ شروع شود.');
    if (!/^\d{16}$/.test(card)) throw bad('شماره کارت باید ۱۶ رقم باشد.');
    if (pw.length < 6 || pw.length > 100) throw bad('رمز عبور حداقل ۶ کاراکتر باشد.');
    if (db.users.some(x => live(x) && x.username.toLowerCase() === username.toLowerCase())) throw bad('این نام کاربری قبلاً گرفته شده است.');
    const user = { id: nid('user'), username, phone, card, pw: hashPw(pw), role: 'user', balance: 0, created_at: now() };
    db.users.push(user); save();
    return { token: sign({ id: user.id }, 30 * 864e5), user: pub(user) };
  }
  if (p === '/login' && m === 'POST') {
    limit(req); const b = await body(req, 1e5);
    const user = db.users.find(x => live(x) && x.username.toLowerCase() === str(b.username, 30).toLowerCase());
    if (!user || !checkPw(b.password, user.pw)) throw bad('نام کاربری یا رمز عبور اشتباه است.', 401);
    if (user.disabled) throw bad('حساب شما مسدود شده است.', 403);
    return { token: sign({ id: user.id }, (user.role === 'admin' ? 12 * 36e5 : 30 * 864e5)), user: pub(user) };
  }
  const user = authUser(req);
  if (p.startsWith('/admin/')) {
    if (user.role !== 'admin') throw bad('دسترسی ندارید', 403);
    return adminApi(req, res, p.slice(6), u);
  }
  if (p === '/me' && m === 'DELETE') {
    const b = await body(req, 1e5);
    if (user.role === 'admin') throw bad('حساب مدیر حذف نمی‌شود.', 403);
    if (!checkPw(b.password, user.pw)) throw bad('رمز عبور اشتباه است.', 403);
    db.orders.concat(db.tx).filter(o => o.user_id === user.id).forEach(o => shotDel(o.code));
    db.orders.concat(db.tx).filter(o => o.user_id === user.id).forEach(o => { delete o.shot_type; });
    Object.assign(user, { deleted: true, pw: '', card: '', phone: '', balance: 0 }); save(); return { ok: true };
  }
  if (p === '/orders' && m === 'POST') {
    limit(req, 60); const b = await body(req);
    const c = db.coins.find(x => x.active && x.name === b.coin);
    if (!c || recv(c) == null) throw bad('این پلتفرم فعلاً فعال نیست.');
    const qty = +b.qty; if (!(qty > 0) || qty > 1e7) throw bad('تعداد سکه نامعتبر است.');
    if (c.cap > 0 && c.stock + qty > c.cap) throw bad('ظرفیت این پلتفرم پر است.');
    const wallet = b.dest === 'wallet', card = str(b.card, 16);
    if (!wallet && !/^\d{16}$/.test(card)) throw bad('شماره کارت باید ۱۶ رقم باشد.');
    const code = newCode('SC-', db.orders), type = shotSave(code, b.screenshot);
    db.orders.push({ code, user_id: user.id, username: user.username, phone: user.phone, kind: 'sell', coin_name: c.name, qty,
      amount: r2(recv(c) * qty), fee: r2((c.sell - recv(c)) * qty), dest: wallet ? 'wallet' : 'card', card: wallet ? '' : card,
      status: 'review', note: '', shot_type: type, created_at: now(), updated_at: now() });
    save(); return { code };
  }
  if (p === '/orders/mine' && m === 'GET')
    return { orders: db.orders.filter(o => o.user_id === user.id).sort((a, b) => b.created_at - a.created_at).map(orderOut) };
  if ((r = /^\/orders\/([\w-]+)\/cancel$/.exec(p)) && m === 'POST') {
    const o = db.orders.find(x => x.code === r[1] && x.user_id === user.id);
    if (!o) throw bad('سفارش پیدا نشد.', 404); if (o.status !== 'review') throw bad('این سفارش دیگر قابل لغو نیست.');
    o.status = 'cancelled'; o.updated_at = now(); save(); return { ok: true };
  }
  if (p === '/wallet' && m === 'GET') {
    const mine = db.tx.filter(t => t.user_id === user.id), sum = k => mine.filter(t => t.kind === k && t.status === 'pending').reduce((a, t) => a + t.amount, 0);
    return { balance: user.balance, pending_topup: sum('topup'), pending_withdraw: sum('withdraw'),
      tx: mine.sort((a, b) => b.created_at - a.created_at).map(txOut) };
  }
  if (p === '/wallet/topup' && m === 'POST') {
    limit(req, 60); const b = await body(req), a = Math.floor(+b.amount);
    if (!(a >= 1000) || a > 1e10) throw bad('مبلغ نامعتبر است.');
    const code = newCode('WL-', db.tx), type = shotSave(code, b.screenshot);
    db.tx.push({ code, user_id: user.id, username: user.username, phone: user.phone, kind: 'topup', amount: a, status: 'pending', note: '', shot_type: type, created_at: now(), updated_at: now() });
    save(); return { code };
  }
  if (p === '/wallet/withdraw' && m === 'POST') {
    limit(req, 60); const b = await body(req, 1e5), a = Math.floor(+b.amount), card = str(b.card, 16);
    if (!(a >= 1000)) throw bad('مبلغ نامعتبر است.');
    if (!/^\d{16}$/.test(card)) throw bad('شماره کارت باید ۱۶ رقم باشد.');
    if (a > user.balance) throw bad('موجودی کافی نیست.');
    user.balance -= a; const code = newCode('WL-', db.tx);
    db.tx.push({ code, user_id: user.id, username: user.username, phone: user.phone, kind: 'withdraw', amount: a, card, status: 'pending', note: '', created_at: now(), updated_at: now() });
    save(); return { code };
  }
  if ((r = /^\/wallet\/([\w-]+)\/cancel$/.exec(p)) && m === 'POST') {
    const t = db.tx.find(x => x.code === r[1] && x.user_id === user.id && (x.kind === 'topup' || x.kind === 'withdraw'));
    if (!t) throw bad('تراکنش پیدا نشد.', 404); if (t.status !== 'pending') throw bad('این تراکنش دیگر قابل لغو نیست.');
    if (t.kind === 'withdraw') user.balance += t.amount;
    t.status = 'cancelled'; t.updated_at = now(); save(); return { ok: true };
  }
  if (p === '/comments' && m === 'POST') {
    limit(req, 30); const b = await body(req, 1e5), text = str(b.text, 1000), rt = Math.round(+b.rating);
    if (text.length < 3) throw bad('نظر خود را بنویسید.');
    db.comments.push({ id: nid('comment'), username: user.username, text, rating: rt >= 1 && rt <= 5 ? rt : null, created_at: now() }); save(); return { ok: true };
  }
  throw bad('آدرس پیدا نشد.', 404);
}

/* ---------------- admin API (/api/admin/*) ---------------- */
function report(days) {
  days = Math.min(365, Math.max(1, +days || 30)); const since = now() - days * 864e5, mp = new Map();
  db.orders.filter(o => o.status === 'confirmed' && o.updated_at >= since).forEach(o => {
    const d = tehranDay(o.updated_at), x = mp.get(d) || { d, buy: 0, sell: 0, profit: 0, orders: 0 };
    if (o.kind === 'buy') x.buy += o.amount; else x.sell += o.amount;
    x.profit += o.fee || 0; x.orders++; mp.set(d, x);
  });
  const daily = [...mp.values()].sort((a, b) => b.d.localeCompare(a.d)).map(x => ({ ...x, buy: r2(x.buy), sell: r2(x.sell), profit: r2(x.profit) }));
  const totals = daily.reduce((a, x) => ({ buy: a.buy + x.buy, sell: a.sell + x.sell, profit: a.profit + x.profit, orders: a.orders + x.orders }), { buy: 0, sell: 0, profit: 0, orders: 0 });
  return { daily, totals };
}
function dashboard() {
  const conf = db.orders.filter(o => o.status === 'confirmed'), today = tehranDay(now()), td = conf.filter(o => tehranDay(o.updated_at) === today);
  const rated = db.comments.filter(c => c.rating), g = new Map();
  conf.forEach(o => { const k = o.coin_name + '|' + o.kind, x = g.get(k) || { coin_name: o.coin_name, kind: o.kind, n: 0, qty: 0, amount: 0 }; x.n++; x.qty += o.qty; x.amount += o.amount; g.set(k, x); });
  return {
    rating: { avg: rated.length ? Math.round(rated.reduce((a, c) => a + c.rating, 0) / rated.length * 10) / 10 : 0, n: rated.length },
    stock_total: db.coins.reduce((a, c) => a + (c.stock || 0), 0),
    pending_orders: db.orders.filter(o => o.status === 'review').length,
    pending_wallet: db.tx.filter(t => t.status === 'pending').length,
    today: { amount: r2(td.reduce((a, o) => a + o.amount, 0)), orders: td.length, qty: td.reduce((a, o) => a + o.qty, 0) },
    users: db.users.filter(u => live(u) && u.role !== 'admin').length,
    wallet_total: db.users.filter(live).reduce((a, u) => a + u.balance, 0),
    coins: [...g.values()].map(x => ({ ...x, amount: r2(x.amount) }))
  };
}
function coinFrom(b, old) {
  const num = (v, d, allowNull) => { if (v === undefined) return d; if (v === '' || v === null) return allowNull ? null : 0; const x = +v; if (!isFinite(x) || x < 0) throw bad('عدد نامعتبر است.'); return x; };
  const c = {
    name: b.name !== undefined ? str(b.name, 40) : old.name,
    color: /^#[0-9a-fA-F]{3,8}$/.test(b.color) ? b.color : (old.color || '#9b6bff'),
    buy: num(b.buy, old.buy, true), sell: num(b.sell, old.sell, true), stock: num(b.stock, old.stock || 0),
    cap: num(b.cap, old.cap || 0), commission: num(b.commission, old.commission || 0), sort: num(b.sort, old.sort || 0),
    active: b.active === undefined ? old.active : !!b.active
  };
  if (!c.name) throw bad('نام سکه را وارد کنید.');
  if (c.commission > 100) throw bad('کارمزد نباید بیشتر از ۱۰۰٪ باشد.');
  if (db.coins.some(x => x !== old && x.name === c.name)) throw bad('این نام قبلاً استفاده شده است.');
  return c;
}
async function adminApi(req, res, p, u) {
  const m = req.method; let r;
  if (p === '/dashboard' && m === 'GET') return dashboard();
  if (p === '/report' && m === 'GET') return report(u.searchParams.get('days'));
  if (p === '/orders' && m === 'GET') {
    const st = u.searchParams.get('status');
    return { orders: db.orders.filter(o => !st || o.status === st).sort((a, b) => b.created_at - a.created_at).map(o => ({ ...orderOut(o), has_shot: !!o.shot_type })) };
  }
  if (p === '/wallet' && m === 'GET')
    return { tx: db.tx.filter(t => t.kind === 'topup' || t.kind === 'withdraw').sort((a, b) => b.created_at - a.created_at).map(t => ({ ...txOut(t), has_shot: !!t.shot_type })) };
  if ((r = /^\/(orders|wallet)\/([\w-]+)\/shot$/.exec(p)) && m === 'GET') {
    const x = (r[1] === 'orders' ? db.orders : db.tx).find(o => o.code === r[2]);
    if (!x || !x.shot_type) throw bad('پیدا نشد.', 404);
    if (pool) {
      await lastSave; const sr = await q('select data from shots where code=$1', [x.code]);
      if (!sr.rows[0]) throw bad('پیدا نشد.', 404);
      res.writeHead(200, { 'content-type': x.shot_type, 'cache-control': 'private, max-age=3600' }); res.end(sr.rows[0].data); return null;
    }
    const f = path.join(DATA, 'shots', x.code);
    if (!fs.existsSync(f)) throw bad('پیدا نشد.', 404);
    res.writeHead(200, { 'content-type': x.shot_type, 'cache-control': 'private, max-age=3600' }); fs.createReadStream(f).pipe(res); return null;
  }
  if ((r = /^\/(orders|wallet)\/([\w-]+)\/(confirm|reject)$/.exec(p)) && m === 'POST') {
    const b = await body(req, 1e5), ord = r[1] === 'orders', x = (ord ? db.orders : db.tx).find(o => o.code === r[2]);
    if (!x) throw bad('پیدا نشد.', 404);
    if (x.status !== (ord ? 'review' : 'pending')) throw bad('این مورد قبلاً بررسی شده است.');
    const owner = db.users.find(z => z.id === x.user_id), ok = r[3] === 'confirm';
    x.status = ok ? 'confirmed' : 'rejected';
    if (ok && ord) {
      const c = db.coins.find(z => z.name === x.coin_name);
      if (c) c.stock = Math.max(0, (c.stock || 0) + (x.kind === 'sell' ? x.qty : -x.qty));
      if (x.dest === 'wallet' && live(owner)) {
        owner.balance += x.amount;
        db.tx.push({ code: newCode('WL-', db.tx), user_id: owner.id, username: owner.username, phone: owner.phone, kind: 'sell_credit', amount: x.amount, status: 'confirmed', note: 'سفارش ' + x.code, created_at: now(), updated_at: now() });
      }
    }
    if (ok && !ord && x.kind === 'topup' && live(owner)) owner.balance += x.amount;
    if (!ok && !ord && x.kind === 'withdraw' && live(owner)) owner.balance += x.amount;
    x.note = str(b.note, 300); x.updated_at = now(); save(); return { ok: true };
  }
  if (p === '/coins' && m === 'GET') return { coins: db.coins.slice().sort((a, b) => a.sort - b.sort || a.id - b.id) };
  if (p === '/coins' && m === 'POST') {
    const c = coinFrom(await body(req, 1e5), { color: '#9b6bff', active: true }); c.id = nid('coin'); db.coins.push(c); save(); return { ok: true };
  }
  if ((r = /^\/coins\/(\d+)$/.exec(p)) && (m === 'PUT' || m === 'DELETE')) {
    const old = db.coins.find(c => c.id === +r[1]); if (!old) throw bad('پیدا نشد.', 404);
    if (m === 'PUT') { Object.assign(old, coinFrom(await body(req, 1e5), old)); save(); return { ok: true }; }
    if (db.orders.some(o => o.coin_name === old.name)) { old.active = false; save(); return { ok: true, note: 'این سکه سابقه‌ی سفارش دارد؛ به‌جای حذف، غیرفعال شد.' }; }
    db.coins = db.coins.filter(c => c !== old); save(); return { ok: true };
  }
  if (p === '/users' && m === 'GET')
    return { users: db.users.slice().reverse().map(x => ({ id: x.id, username: x.username, phone: x.phone, card: x.card, balance: x.balance, role: x.role || 'user',
      orders: db.orders.filter(o => o.user_id === x.id).length, created_at: x.created_at, deleted: !!x.deleted, disabled: !!x.disabled })) };
  if ((r = /^\/users\/(\d+)\/toggle$/.exec(p)) && m === 'POST') {
    const x = db.users.find(z => z.id === +r[1]); if (!x || x.role === 'admin') throw bad('پیدا نشد.', 404);
    x.disabled = !x.disabled; save(); return { ok: true };
  }
  if (p === '/comments' && m === 'GET') return { items: db.comments.slice().reverse() };
  if (p === '/announcements' && m === 'GET') return { items: db.announcements.slice().reverse() };
  if (p === '/announcements' && m === 'POST') {
    const t = str((await body(req, 1e5)).text, 300); if (t.length < 2) throw bad('متن اعلان را بنویسید.');
    db.announcements.push({ id: nid('ann'), text: t, active: true, created_at: now() }); save(); return { ok: true };
  }
  if ((r = /^\/announcements\/(\d+)(\/toggle)?$/.exec(p))) {
    const a = db.announcements.find(z => z.id === +r[1]); if (!a) throw bad('پیدا نشد.', 404);
    if (r[2] && m === 'POST') { a.active = !a.active; save(); return { ok: true }; }
    if (!r[2] && m === 'DELETE') { db.announcements = db.announcements.filter(z => z !== a); save(); return { ok: true }; }
  }
  if (p === '/settings' && m === 'GET') return { settings: db.settings };
  if (p === '/settings' && m === 'PUT') {
    const b = await body(req, 1e5), card = str(b.owner_card, 19).replace(/\D/g, '');
    if (card && card.length !== 16) throw bad('شماره کارت باید ۱۶ رقم باشد.');
    db.settings = { owner_card: card, owner_phone: str(b.owner_phone, 20), support_id: idStr(b.support_id), channel_id: idStr(b.channel_id), buy_enabled: b.buy_enabled === '1' ? '1' : '0' };
    save(); return { ok: true };
  }
  throw bad('آدرس پیدا نشد.', 404);
}

const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.webp': 'image/webp', '.json': 'application/json' };
const FLAT = !fs.existsSync(PUB);
function serveStatic(res, p) {
  const k = (p === '/' || p === '/index.html') ? 'index.html' : (p === '/admin' || p === '/admin.html') ? 'admin.html' : null;
  if (!k) { res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' }); return res.end('پیدا نشد'); }
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' });
  return res.end(Buffer.from(EMBED[k], 'base64'));
  if (p === '/admin') p = '/admin.html'; if (p === '/') p = '/index.html';
  const base = FLAT ? __dirname : PUB, f = path.normalize(path.join(base, p));
  const okName = !FLAT || p === '/index.html' || p === '/admin.html';
  if (!okName || !f.startsWith(base + path.sep) || !fs.existsSync(f) || !fs.statSync(f).isFile()) { res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' }); return res.end('پیدا نشد'); }
  res.writeHead(200, { 'content-type': MIME[path.extname(f)] || 'application/octet-stream', 'cache-control': 'no-cache' });
  fs.createReadStream(f).pipe(res);
}

const server = http.createServer(async (req, res) => {
  res.setHeader('x-content-type-options', 'nosniff'); res.setHeader('referrer-policy', 'same-origin');
  try {
    const u = new URL(req.url, 'http://x'), p = u.pathname;
    if (p === '/health') { res.writeHead(200, { 'content-type': 'text/plain' }); return res.end('ok'); }
    if (!p.startsWith('/api/')) return serveStatic(res, decodeURIComponent(p));
    const out = await api(req, res, p.slice(4), u);
    if (out === null) return;
    await lastSave;
    res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }); res.end(JSON.stringify(out));
  } catch (e) {
    const s = e.status || 500; if (s === 500) console.error(e);
    if (!res.headersSent) res.writeHead(s, { 'content-type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ error: s === 500 ? 'خطای داخلی سرور' : e.message }));
  }
});
if (process.env.RENDER_EXTERNAL_URL) setInterval(() => { fetch(process.env.RENDER_EXTERNAL_URL + '/health').catch(() => {}); }, 10 * 60 * 1000);
init().then(() => server.listen(PORT, () => console.log('listening on ' + PORT)))
  .catch(e => { console.error('startup failed:', e.message); process.exit(1); });

setInterval(() => {
  if (!db) return;
  const old = x => x.status === 'cancelled' && now() - x.updated_at > 300000;
  const dead = [...db.orders.filter(old), ...db.tx.filter(old)];
  if (!dead.length) return;
  dead.forEach(x => shotDel(x.code));
  db.orders = db.orders.filter(x => !old(x)); db.tx = db.tx.filter(x => !old(x)); save();
}, 60000);
